/// What a scenario's own steps did, as its after hook sees it.
///
/// It is the result of the scenario body alone. Everything the after hook does afterwards is
/// cleanup, and cleanup reports itself separately, so a log line never blames a scenario for what
/// its teardown found.
#[derive(Debug)]
enum ScenarioBodyResult {
    Passed,
    Skipped,
    BeforeHookFailed,
    StepFailed(String),
}

impl From<&ScenarioFinished> for ScenarioBodyResult {
    fn from(finished: &ScenarioFinished) -> Self {
        match finished {
            ScenarioFinished::StepPassed => Self::Passed,
            ScenarioFinished::StepSkipped => Self::Skipped,
            ScenarioFinished::BeforeHookFailed(_) => Self::BeforeHookFailed,
            ScenarioFinished::StepFailed(_, _, error) => {
                Self::StepFailed(error.to_string().replace('\n', "\\n"))
            }
        }
    }
}

impl fmt::Display for ScenarioBodyResult {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Passed => formatter.write_str("passed"),
            Self::Skipped => formatter.write_str("skipped"),
            Self::BeforeHookFailed => formatter.write_str("before hook failed"),
            Self::StepFailed(error) => write!(formatter, "step failed: {error}"),
        }
    }
}

#[derive(Clone, Debug)]
struct DurableCatchUpObservation {
    follower: String,
    initial_leader: String,
    commit_delay: Duration,
    started_at: Instant,
    append_stream_opens_at_start: BTreeMap<String, u64>,
}

#[derive(Clone, Debug)]
struct AppendSetupObservation {
    target: String,
    started_at: Instant,
    attempts_at_start: BTreeMap<String, u64>,
}

struct DurableCatchUpWriter {
    cancellation: CancellationToken,
    prefix: String,
    task: AbortOnDropHandle<Result<usize, String>>,
}

/// Client sessions that keep committing domain creations through the leader, each waiting for its
/// previous command, until a step stops them.
struct DomainWriteLoad {
    cancellation: CancellationToken,
    prefix: String,
    /// Each session's task answers how many domains it committed.
    sessions: Vec<AbortOnDropHandle<Result<usize, String>>>,
}

/// HTTPS posts to every node that keep running until a step collects what the listeners answered.
struct BackgroundHttpsPublish {
    stop: CancellationToken,
    task: AbortOnDropHandle<HttpsPublishLoopOutcome>,
}

/// A follower's commands-class memory, sampled for the whole time it spends catching up.
///
/// The batches it has decoded and not yet answered are charged to that class, and they are held
/// only while its Raft core is behind. Sampling throughout catches the peak the catch-up reached
/// rather than whatever the class happened to hold once it was over.
struct FollowerCommandsMemoryObservation {
    node_id: String,
    cancellation: CancellationToken,
    task: AbortOnDropHandle<f64>,
}

/// Evidence retained across the replication and restart phases of the large transaction report
/// qualification scenario.
#[derive(Debug)]
struct TransactionQualificationObservation {
    leader: String,
    retention_before: nervix_consensus::RaftLogRetention,
    committed_inspection: Option<Box<nervix_models::TransactionInspection>>,
}

#[derive(Debug)]
struct SavedHealthyPlacement {
    kind: String,
    name: String,
    owner: String,
}

/// A Syslog TCP or TLS connection that wrote one complete frame and the start of a second one,
/// and the bytes of that second frame it has not written yet.
struct SyslogSplitSender {
    stream: Box<dyn tokio::io::AsyncWrite + Send + Sync + Unpin>,
    rest: Vec<u8>,
}

/// A connection to a Syslog listener that never writes, and the task that reads it until the
/// listener ends it.
struct SilentSyslogClient {
    /// An instant before the connection opened, so no deadline the listener started for it can
    /// have started earlier.
    connecting_at: Instant,
    ended: AbortOnDropHandle<SilentSyslogClientEnd>,
}

/// How the listener ended a connection that sent nothing.
enum SilentSyslogClientEnd {
    /// The listener closed or reset the connection at this instant.
    Closed(Instant),
    /// The listener sent bytes, which no Syslog listener does.
    Answered,
    /// Reading the connection failed in another way.
    Failed(std::io::Error),
}

/// One long-running CLI clock follower and the bounded stdout lines its assertions inspect.
struct CliClockProcess {
    child: tokio::process::Child,
    lines: StdArc<BlockingMutex<VecDeque<String>>>,
    _reader: AbortOnDropHandle<()>,
}

/// How one node start that a scenario attempted, without requiring it to succeed, ended.
#[derive(Debug)]
struct NodeStartAttempt {
    node: String,
    /// The startup's failure rendered with its whole report, or nothing when the node started.
    failure: Option<String>,
}

/// The next row and the subscription session returned by its independent receipt observer.
struct SubscriptionReceipt {
    session: TestSession,
    event: TestSubscriptionEvent,
}

