#[given(expr = "client {string} is connected to the server process")]
async fn given_named_client_is_connected_to_server_process(
    world: &mut ScenarioWorld,
    name: String,
) {
    let name = expand_placeholders(world, &name);
    let grpc_uri = world
        .server_process
        .as_ref()
        .verified("the preceding step started a real server process")
        .grpc_uri();
    let options = client_connect_options(&grpc_uri).expect("server process client options");
    let client = Client::connect_with_options(&grpc_uri, client_domain(&world.domain), options)
        .await
        .unwrap_or_else(|error| {
            panic!("failed to connect client '{name}' to the process: {error}")
        });
    assert!(
        world
            .transaction_clients
            .insert(name.clone(), client)
            .is_none(),
        "client '{name}' is already connected"
    );
}

#[given(
    expr = "client {string} is connected to the leader node as user {string} with password \
            {string}"
)]
async fn given_named_client_is_connected_to_leader_as_user(
    world: &mut ScenarioWorld,
    name: String,
    username: String,
    password: String,
) {
    let name = expand_placeholders(world, &name);
    let leader = current_leader_node(world).await;
    let grpc_uri = world
        .cluster()
        .grpc_uri(&leader)
        .expect("failed to resolve leader gRPC URI");
    let mut options =
        client_connect_options(&grpc_uri).expect("failed to build client tls options");
    options.username = Some(expand_placeholders(world, &username));
    options.password = Some(expand_placeholders(world, &password));
    let client = Client::connect_with_options(&grpc_uri, client_domain(&world.domain), options)
        .await
        .unwrap_or_else(|error| {
            panic!("failed to connect client '{name}' as '{username}': {error}")
        });
    assert!(
        world
            .transaction_clients
            .insert(name.clone(), client)
            .is_none(),
        "client '{name}' is already connected"
    );
}

#[when(expr = "client {string} closes its session cleanly")]
async fn when_named_client_closes_cleanly(world: &mut ScenarioWorld, name: String) {
    let name = expand_placeholders(world, &name);
    let client = world
        .transaction_clients
        .remove(&name)
        .unwrap_or_else(|| panic!("client '{name}' must be connected"));
    drop(client);
}

#[when(expr = "client {string} executes these Plexus commands")]
#[when(expr = "client {string} executes these Plexus statements")]
async fn when_named_client_executes_commands(
    world: &mut ScenarioWorld,
    name: String,
    #[step] step: &Step,
) {
    world.last_command_error = None;
    world.last_command_output = None;
    world.last_client_outcome = None;
    let name = expand_placeholders(world, &name);
    let commands = expand_placeholders(world, docstring(step));
    let client = world
        .transaction_clients
        .get(&name)
        .unwrap_or_else(|| panic!("client '{name}' must be connected"))
        .clone();
    for command in plexus_statements(&commands) {
        nervix_primitives::task::consume_budget().await;
        let outcome = client
            .execute(command.clone())
            .await
            .unwrap_or_else(|error| panic!("client '{name}' command failed: {command}: {error}"));
        assert!(
            outcome.succeeded(),
            "client '{name}' command must succeed: {command}: {}",
            outcome.message
        );
        world.last_command_output = Some(outcome.message.clone());
        world.last_client_outcome = Some(outcome);
    }
}

#[when(expr = "client {string} submits this Plexus command request")]
async fn when_named_client_submits_command_request(
    world: &mut ScenarioWorld,
    name: String,
    #[step] step: &Step,
) {
    world.last_command_error = None;
    world.last_command_output = None;
    world.last_client_outcome = None;
    let name = expand_placeholders(world, &name);
    let request = expand_placeholders(world, docstring(step));
    let client = world
        .transaction_clients
        .get(&name)
        .unwrap_or_else(|| panic!("client '{name}' must be connected"))
        .clone();
    let outcome = client
        .execute(request.clone())
        .await
        .unwrap_or_else(|error| panic!("client '{name}' request failed: {request}: {error}"));
    if outcome.succeeded() {
        world.last_command_output = Some(outcome.message.clone());
    } else {
        world.last_command_error = Some(outcome.message.clone());
    }
    world.last_client_outcome = Some(outcome);
    world.last_client_request = Some(request);
}

/// Measures a command batch on a client prepared before the fault, with its reply polled
/// independently of the Cucumber runner. The deadline includes dispatch to the runtime task.
/// Every node's control-class execution and reactor delay are read beside the probe and reported
/// for its window, so a slow batch shows where its nodes' scheduling went.
#[then(expr = "within {string} client {string} completes these Plexus statements")]
async fn then_named_client_completes_plexus_statements_within(
    world: &mut ScenarioWorld,
    duration: String,
    name: String,
    #[step] step: &Step,
) {
    let limit = parse_duration_text(&duration).assured("the scenario duration is valid");
    let name = expand_placeholders(world, &name);
    let Some(client) = world.transaction_clients.get(&name) else {
        panic!("client '{name}' must be connected before the timed probe");
    };
    let client = client.clone();
    let probe_domain = world.domain.clone();
    let commands = expand_placeholders(world, docstring(step));
    let statements = plexus_statements(&commands);
    assert!(!statements.is_empty(), "a timed probe requires statements");
    let mut execution_endpoints = Vec::new();
    for node_id in world.cluster().node_ids() {
        let metrics_url = world
            .cluster()
            .observability_metrics_url(&node_id)
            .assured("the node was listed by the same cluster");
        execution_endpoints.push(NodeExecutionEndpoint::new(node_id, metrics_url));
    }
    world.last_command_error = None;
    world.last_command_output = None;
    world.last_client_outcome = None;
    let started = Instant::now();
    let deadline = started
        .checked_add(limit)
        .assured("the scenario duration fits a monotonic instant");
    let (outcome, elapsed) =
        crate::common::runner_observation::observe_off_the_runner(async move {
            let execution = ProbeExecution::begin(execution_endpoints);
            let mut last_outcome = None;
            for (position, statement) in statements.into_iter().enumerate() {
                nervix_primitives::task::consume_budget().await;
                append_cucumber_log_line(&format!(
                    "Plexus control dispatch: client={name} domain={probe_domain} \
                     position={position} elapsed={:?}",
                    started.elapsed()
                ));
                let Ok(reply) =
                    nervix_primitives::time::timeout_at(deadline, client.execute(statement)).await
                else {
                    let execution = execution.describe().await;
                    log_probe_execution(&name, &probe_domain, &execution);
                    panic!(
                        "client '{name}' did not complete the Plexus statements within {limit:?}; \
                         pending statement {position}; domain={probe_domain}; execution over the \
                         probe: {}",
                        execution.join("; ")
                    )
                };
                let outcome = reply.unwrap_or_else(|error| {
                    panic!("client '{name}' failed at Plexus statement {position}: {error:#}")
                });
                let completed_at = Instant::now();
                let elapsed = completed_at.duration_since(started);
                assert!(
                    elapsed <= limit,
                    "client '{name}' completed Plexus statement {position} after {limit:?}: \
                     {elapsed:?}; domain={probe_domain}"
                );
                assert!(
                    outcome.succeeded(),
                    "client '{name}' Plexus statement {position} must succeed: {}",
                    outcome.message
                );
                append_cucumber_log_line(&format!(
                    "Plexus control statement: client={name} domain={probe_domain} \
                     position={position} elapsed={elapsed:?}"
                ));
                last_outcome = Some((outcome, completed_at));
            }
            let (outcome, completed_at) =
                last_outcome.assured("each statement in the nonempty probe answered");
            let elapsed = completed_at.duration_since(started);
            append_cucumber_log_line(&format!(
                "Plexus control probe: client={name} domain={probe_domain} elapsed={elapsed:?} \
                 limit={limit:?}"
            ));
            let execution = execution.describe().await;
            log_probe_execution(&name, &probe_domain, &execution);
            (outcome, elapsed)
        })
        .await;
    world.last_command_output = Some(crate::common::cluster::flatten_outcome_messages(&outcome));
    world.last_client_outcome = Some(outcome);
    world.last_cluster_operation_elapsed = Some(elapsed);
}

fn log_probe_execution(client: &str, domain: &str, execution: &[String]) {
    for node in execution {
        append_cucumber_log_line(&format!(
            "Plexus control execution: client={client} domain={domain} {node}"
        ));
    }
}

#[when(expr = "client {string} fails to execute these Plexus commands")]
async fn when_named_client_fails_to_execute_commands(
    world: &mut ScenarioWorld,
    name: String,
    #[step] step: &Step,
) {
    world.last_command_error = None;
    world.last_command_output = None;
    let name = expand_placeholders(world, &name);
    let commands = expand_placeholders(world, docstring(step));
    let client = world
        .transaction_clients
        .get(&name)
        .unwrap_or_else(|| panic!("client '{name}' must be connected"))
        .clone();
    for command in plexus_statements(&commands) {
        nervix_primitives::task::consume_budget().await;
        match client.execute(command.clone()).await {
            Ok(outcome) if outcome.succeeded() => {
                world.last_command_output = Some(outcome.message);
            }
            Ok(outcome) => {
                world.last_command_error = Some(outcome.message);
                return;
            }
            Err(error) => {
                world.last_command_error = Some(format!("{error:#}"));
                return;
            }
        }
    }
    panic!("client '{name}' commands unexpectedly succeeded");
}

