#[then(
    expr = "the transaction targeted by execution reference {string} is saved as placeholder \
            {string}"
)]
async fn then_execution_transaction_is_saved(
    world: &mut ScenarioWorld,
    execution_reference: String,
    placeholder: String,
) {
    let reference = command_execution_reference(world, &execution_reference);
    let reference = nervix_models::CommandExecutionReference::parse(reference)
        .assured("scenario command references are valid UUIDv7 values");
    let leader = current_leader_node(world).await;
    let observer = world
        .fault_injection
        .consensus_observer(&crate::common::cluster::node_name(&leader));
    let execution = observer
        .current_command_execution(&reference)
        .await
        .verified("the preceding finalization pause holds an admitted execution");
    let transaction_id = match execution.effect() {
        Some(nervix_consensus::CommandExecutionEffect::Transaction { transaction_id, .. }) => {
            transaction_id.clone()
        }
        Some(nervix_consensus::CommandExecutionEffect::TransactionRequest(request)) => {
            request.target.id().to_string()
        }
        _ => panic!("execution '{reference}' must target a transaction"),
    };
    world.placeholders.insert(placeholder, transaction_id);
}

#[then(expr = "transaction {string} eventually has state {string}")]
async fn then_transaction_eventually_has_state(
    world: &mut ScenarioWorld,
    transaction_id: String,
    expected_state: String,
) {
    let transaction_id = expand_placeholders(world, &transaction_id);
    let expected_state = expand_placeholders(world, &expected_state).to_ascii_uppercase();
    let leader = current_leader_node(world).await;
    let expected_id = format!("id={transaction_id}");
    let expected_state_fragment = format!("state={expected_state}");
    // A state such as EXPIRED arrives only after a configured timer, and a loaded node reports it
    // later still. The wait ends as soon as the state is listed, so its bound is generous.
    let deadline = Instant::now() + Duration::from_secs(60);
    let mut last_output = String::new();
    loop {
        nervix_primitives::task::consume_budget().await;
        assert!(
            Instant::now() < deadline,
            "transaction '{transaction_id}' did not reach state '{expected_state}'; last output: \
             {last_output}"
        );
        match world
            .cluster()
            .run_command(&leader, &world.domain, "SHOW TRANSACTIONS;")
            .await
        {
            Ok(output) => {
                if output.lines().any(|line| {
                    line.contains(&expected_id) && line.contains(&expected_state_fragment)
                }) {
                    world.last_command_output = Some(output);
                    return;
                }
                last_output = output;
            }
            Err(error) => last_output = error.to_string(),
        }
        nervix_primitives::time::sleep(Duration::from_millis(50)).await;
    }
}

fn quiescence_outcome_name(outcome: &nervix_models::QuiescenceOutcome) -> &'static str {
    match outcome {
        nervix_models::QuiescenceOutcome::Requested => "REQUESTED",
        nervix_models::QuiescenceOutcome::Confirmed => "CONFIRMED",
        nervix_models::QuiescenceOutcome::Failed { .. } => "FAILED",
        nervix_models::QuiescenceOutcome::Uncertain { .. } => "UNCERTAIN",
        nervix_models::QuiescenceOutcome::Released => "RELEASED",
    }
}

fn execution_outcome_name(outcome: &nervix_models::ExecutionStepOutcome) -> &'static str {
    match outcome {
        nervix_models::ExecutionStepOutcome::Unattempted => "UNATTEMPTED",
        nervix_models::ExecutionStepOutcome::Applying => "APPLYING",
        nervix_models::ExecutionStepOutcome::Applied => "APPLIED",
        nervix_models::ExecutionStepOutcome::Failed { .. } => "FAILED",
    }
}

async fn read_transaction_impact_report(
    world: &ScenarioWorld,
    transaction_id: &str,
) -> Result<nervix_models::TransactionImpactReport, String> {
    let leader = current_leader_node(world).await;
    let observer = world
        .fault_injection
        .consensus_observer(&crate::common::cluster::node_name(&leader));
    let transaction = observer
        .current_transaction(transaction_id)
        .await
        .ok_or_else(|| format!("transaction '{transaction_id}' is not retained"))?;
    let preview = transaction
        .latest_preview()
        .ok_or_else(|| format!("transaction '{transaction_id}' has no retained preview"))?;
    observer
        .current_transaction_report(preview)
        .await
        .map_err(|error| error.to_string())
}

#[given(expr = "a stopped transaction qualification graph with {int} relays is configured")]
async fn given_stopped_transaction_qualification_graph(
    world: &mut ScenarioWorld,
    relay_count: usize,
) {
    let leader = current_leader_node(world).await;
    let grpc_uri = world
        .cluster()
        .grpc_uri(&leader)
        .expect("failed to resolve the transaction qualification setup leader");
    let mut options =
        client_connect_options(&grpc_uri).expect("transaction qualification client options");
    for node in world.cluster().node_ids() {
        let seed = world
            .cluster()
            .grpc_uri(&node)
            .expect("transaction qualification seed node has a gRPC URI");
        options
            .seed_servers
            .push(url::Url::parse(&seed).expect("cluster gRPC seed URIs are valid URLs"));
    }
    let client = Client::connect_with_options(&grpc_uri, client_domain(&world.domain), options)
        .await
        .unwrap_or_else(|error| {
            panic!("failed to connect the transaction qualification setup client: {error}")
        });
    let outcome = client
        .execute("CREATE SCHEMA qualification_event ( value I64 );")
        .await
        .unwrap_or_else(|error| {
            panic!("failed to create the transaction qualification schema: {error}")
        });
    assert!(
        outcome.succeeded(),
        "transaction qualification schema creation must succeed: {}",
        outcome.message
    );
    for index in 0..relay_count {
        nervix_primitives::task::consume_budget().await;
        let relay = format!("qualification_relay_{index:04}");
        let command =
            format!("CREATE RELAY {relay} SCHEMA qualification_event UNBRANCHED CAPACITY 1;");
        let outcome = client
            .execute(command)
            .await
            .unwrap_or_else(|error| panic!("failed to create relay '{relay}': {error}"));
        assert!(
            outcome.succeeded(),
            "transaction qualification relay '{relay}' creation must succeed: {}",
            outcome.message
        );
    }
}

