#[then(
    expr = "within {string} the {int} branches of WASM PROCESSOR {string} have committed revision \
            {int} with {int} confirmed replicas"
)]
async fn then_all_wasm_branches_have_confirmed_checkpoint(
    world: &mut ScenarioWorld,
    duration: String,
    branch_count: usize,
    processor: String,
    revision: u64,
    replicas: usize,
) {
    let duration = parse_duration_text(&duration).expect("step duration must be valid");
    let deadline = Instant::now() + duration;
    // The scenario reconnects its subscription to a live node after owner loss. Inspect through
    // that same node: the cluster-wide leader helper waits on stopped nodes as well as live ones.
    let node = match world.active_session_node.clone() {
        Some(node) => node,
        None => current_leader_node(world).await,
    };
    let expected = format!(
        "committed_revision={revision} latest_revision={revision} stage=REPLICA_CONFIRMED \
         required_replicas={replicas} confirmed_replicas={replicas}"
    );
    loop {
        nervix_primitives::task::consume_budget().await;
        let output = run_plexus_commands_on_node(
            world,
            &node,
            &format!("DESCRIBE WASM PROCESSOR {processor};"),
        )
        .await
        .expect("describe wasm processor command must succeed");
        let checkpoints = output
            .lines()
            .filter(|line| line.trim_start().starts_with("checkpoint branch="))
            .collect::<Vec<_>>();
        if output.contains(&format!("state structures: {branch_count}"))
            && output.contains("failed checkpoints: 0")
            && checkpoints.len() == branch_count
            && checkpoints.iter().all(|line| line.contains(&expected))
        {
            return;
        }
        assert!(
            Instant::now() < deadline,
            "timed out waiting for {branch_count} branch checkpoints at revision {revision} with \
             {replicas} replicas. last output: {output}"
        );
        nervix_primitives::time::sleep(Duration::from_millis(100)).await;
    }
}

#[then(expr = "the last client outcome reports WASM reset phase {string} at generation {int}")]
fn then_last_client_outcome_reports_wasm_reset(
    world: &mut ScenarioWorld,
    phase: String,
    generation: u64,
) {
    let outcome = world
        .last_client_outcome
        .as_ref()
        .assured("the preceding step executed a client command");
    let state = outcome
        .wasm_state
        .as_ref()
        .assured("the preceding command described a WASM processor");
    let reset = state
        .reset
        .as_ref()
        .assured("the preceding transaction published a WASM state reset");
    assert_eq!(reset.reset.phase().as_ref(), phase);
    assert_eq!(u64::from(reset.generation), generation);
}

/// Assert that one of two emitters reports the given text.
///
/// Which of two peers contending for the last connection ends up holding it and which ends up
/// waiting is a race, and the claim under test is about the waiter rather than about a particular
/// name, so naming one of them would test the race instead of the behaviour.
#[then(expr = "within {string} DESCRIBE EMITTER {string} or {string} on the leader node contains")]
async fn then_describe_one_of_two_emitters_contains(
    world: &mut ScenarioWorld,
    duration: String,
    first: String,
    second: String,
    #[step] step: &Step,
) {
    let duration = parse_duration_text(&duration).expect("step duration must be a valid duration");
    let emitters = [
        expand_placeholders(world, &first),
        expand_placeholders(world, &second),
    ];
    let expected = expand_placeholders(world, docstring(step));
    let deadline = Instant::now() + duration;

    loop {
        nervix_primitives::task::consume_budget().await;
        let leader = current_leader_node(world).await;
        let mut outputs = Vec::with_capacity(emitters.len());
        for emitter in &emitters {
            let output = run_plexus_commands_on_node(
                world,
                &leader,
                &format!("DESCRIBE EMITTER {emitter};"),
            )
            .await
            .expect("describe emitter command must succeed");
            if output.contains(expected.trim()) {
                world.last_command_output = Some(output);
                return;
            }
            outputs.push(output);
        }
        assert!(
            Instant::now() < deadline,
            "timed out waiting for {} or {} to contain {}. last outputs: {outputs:?}",
            emitters[0],
            emitters[1],
            expected.trim()
        );
        nervix_primitives::time::sleep(Duration::from_millis(100)).await;
    }
}

