#[then(expr = "within {string} the relay subscription receives payloads")]
async fn then_within_duration_the_stream_subscription_receives_payloads(
    world: &mut ScenarioWorld,
    duration: String,
    #[step] step: &Step,
) {
    let duration = parse_duration_text(&duration).expect("step duration must be a valid duration");
    let expected_fragments = expected_payload_fragments(world, step);
    await_subscription_payloads(world, duration, &expected_fragments, None).await;
}

/// Delays collection of the sample's result while its reader must keep the original deadline.
/// Only this scenario awaits the injected delay; every other scenario can continue running.
#[then(
    expr = "within {string} the relay subscription receives payloads with its caller delayed by \
            {string}"
)]
async fn then_subscription_payloads_survive_a_delayed_caller(
    world: &mut ScenarioWorld,
    duration: String,
    caller_delay: String,
    #[step] step: &Step,
) {
    let duration = parse_duration_text(&duration).assured("the receive budget is a valid duration");
    let caller_delay =
        parse_duration_text(&caller_delay).assured("the injected caller delay is a valid duration");
    assert!(
        caller_delay > duration,
        "the controlled caller delay must outlast the receive budget"
    );
    let expected_fragments = expected_payload_fragments(world, step);
    await_subscription_payloads(world, duration, &expected_fragments, Some(caller_delay)).await;
}

/// Measures an input collector's hold instead of asserting silence while its window runs. Each
/// collector's window opens no earlier than the first record that reaches it, which was posted no
/// earlier than the scenario's first HTTP post, so the collected payloads cannot be read sooner
/// than the window after that post. This step must start while the window is still open: then it
/// reads each payload as it arrives, and a step that starts late can only lengthen the measured
/// delay.
#[then(
    expr = "within {string} the relay subscription receives payloads no sooner than {string} \
            after the first http payload was posted"
)]
async fn then_within_duration_the_relay_subscription_receives_payloads_after_collection(
    world: &mut ScenarioWorld,
    duration: String,
    delay: String,
    #[step] step: &Step,
) {
    let duration = parse_duration_text(&duration).expect("step duration must be a valid duration");
    let expected_delay = parse_duration_text(&delay).expect("step delay must be a valid duration");
    let first_posted_at = world
        .first_http_post_at
        .expect("a collection-delay assertion must follow an http post");
    let expected_fragments = expected_payload_fragments(world, step);

    let first_read_at =
        await_subscription_payloads(world, duration, &expected_fragments, None).await;

    let first_read_after = first_read_at.duration_since(first_posted_at);
    append_cucumber_log_line(&format!(
        "first collected subscription payload was read {first_read_after:?} after the first http \
         post"
    ));
    assert!(
        first_read_after >= expected_delay,
        "expected the collected payloads no sooner than {expected_delay:?} after the first http \
         post, but the first was read after {first_read_after:?}"
    );
}

/// The payload fragments a step's docstring expects, one for each non-empty line.
fn expected_payload_fragments(world: &ScenarioWorld, step: &Step) -> Vec<String> {
    let expected_fragments = docstring(step)
        .lines()
        .map(str::trim)
        .filter(|line| !line.is_empty())
        .map(|line| expand_placeholders(world, line))
        .collect::<Vec<_>>();
    assert!(
        !expected_fragments.is_empty(),
        "step docstring must contain at least one expected payload fragment"
    );
    expected_fragments
}

impl common::subscription_payloads::PayloadSubscription for TestSession {
    async fn next_payload(&mut self, budget: Duration) -> std::io::Result<Option<String>> {
        let event = self.try_next_subscription(budget).await?;
        Ok(event.map(|event| event.payload))
    }
}

/// Reads the active session's subscription until every expected fragment has arrived as often as
/// it is listed, failing once `duration` has passed, and returns when the first payload was read.
async fn await_subscription_payloads(
    world: &mut ScenarioWorld,
    duration: Duration,
    expected_fragments: &[String],
    caller_delay: Option<Duration>,
) -> Instant {
    let session = world
        .active_session
        .take()
        .assured("the scenario opened its subscription before receiving payloads");
    let began_at = Instant::now();
    let observation = common::subscription_payloads::SubscriptionPayloads::new(expected_fragments);
    let observation = observation.observe(session, duration);
    if let Some(caller_delay) = caller_delay {
        nervix_primitives::time::sleep(caller_delay).await;
    }
    let observed = observation.await;
    world.active_session = Some(observed.subscription);
    for receipt in &observed.receipts {
        append_cucumber_log_line(&format!(
            "subscription sample receipt after {:?}, budget {duration:?}: {}",
            receipt.received_at.duration_since(began_at),
            receipt.payload
        ));
    }
    let first = observed
        .receipts
        .first()
        .verified("a complete nonempty sample received at least one payload");
    world.last_subscription_payload = observed
        .receipts
        .last()
        .map(|receipt| receipt.payload.clone());
    first.received_at
}

#[then(
    expr = "within {string} subscriptions {string} and {string} each pass between {int} and {int} \
            of the metric values up to {int}"
)]
async fn then_subscriptions_each_sample_metric_values(
    world: &mut ScenarioWorld,
    duration: String,
    first: String,
    second: String,
    fewest: usize,
    most: usize,
    sampled_up_to: i64,
) {
    /// What one subscription delivered while this step read it.
    #[derive(Default)]
    struct SubscriptionSample {
        /// The values up to the sampled bound, in the order they arrived.
        passed: Vec<i64>,
        /// The last value of any kind that arrived.
        last: Option<i64>,
        /// Whether a value above the bound arrived. Rows arrive in the order they were
        /// published, so every value up to the bound has been drawn for by then.
        drawn: bool,
    }

    let duration = parse_duration_text(&duration)
        .assured("the scenario sampling deadline is a valid duration");
    let session = world
        .active_session
        .as_mut()
        .expect("an active session with the sampled subscriptions must exist");
    let mut samples = BTreeMap::new();
    samples.insert(first.clone(), SubscriptionSample::default());
    samples.insert(second.clone(), SubscriptionSample::default());
    let deadline = Instant::now() + duration;
    loop {
        nervix_primitives::task::consume_budget().await;
        let mut all_drawn = true;
        for sample in samples.values() {
            if !sample.drawn {
                all_drawn = false;
            }
        }
        if all_drawn {
            break;
        }
        let now = Instant::now();
        assert!(
            now < deadline,
            "timed out before '{first}' and '{second}' drew for every metric value up to \
             {sampled_up_to}"
        );
        let event = session
            .try_next_subscription(deadline.saturating_duration_since(now))
            .await
            .expect("failed while waiting for sampled subscription rows")
            .unwrap_or_else(|| {
                panic!(
                    "timed out before '{first}' and '{second}' drew for every metric value up to \
                     {sampled_up_to}"
                )
            });
        let payload = serde_json::from_str::<serde_json::Value>(&event.payload)
            .unwrap_or_else(|error| panic!("subscription payload is not valid JSON: {error}"));
        let Some(value) = payload.get("value").and_then(serde_json::Value::as_i64) else {
            panic!("subscription payload {payload} has no integer 'value'");
        };
        let subscription = event.subscription.as_str();
        let Some(sample) = samples.get_mut(subscription) else {
            panic!("subscription '{subscription}' delivered a row this step does not sample");
        };
        if let Some(last) = sample.last {
            assert!(
                value > last,
                "subscription '{subscription}' delivered {value} after {last}, out of the order \
                 the values were published in"
            );
        }
        sample.last = Some(value);
        if value > sampled_up_to {
            sample.drawn = true;
        } else {
            sample.passed.push(value);
        }
    }

    let mut sampled = BTreeMap::new();
    for (subscription, sample) in samples {
        let passed = sample.passed.len();
        assert!(
            (fewest..=most).contains(&passed),
            "subscription '{subscription}' passed {passed} of the metric values up to \
             {sampled_up_to}, not between {fewest} and {most}: {:?}",
            sample.passed
        );
        sampled.insert(subscription, sample.passed);
    }
    world.sampled_metric_values = sampled;
}

#[then(expr = "subscriptions {string} and {string} passed different metric values")]
async fn then_subscriptions_passed_different_metric_values(
    world: &mut ScenarioWorld,
    first: String,
    second: String,
) {
    let first_values = world
        .sampled_metric_values
        .get(&first)
        .unwrap_or_else(|| panic!("no earlier step recorded the values '{first}' passed"));
    let second_values = world
        .sampled_metric_values
        .get(&second)
        .unwrap_or_else(|| panic!("no earlier step recorded the values '{second}' passed"));
    assert_ne!(
        first_values, second_values,
        "subscriptions on one node take their draws from one sequence, so '{first}' and \
         '{second}' must not pass the same values"
    );
}

#[then(expr = "within {string} {int} relay subscription payloads share field {string}")]
async fn then_relay_subscription_payloads_share_field(
    world: &mut ScenarioWorld,
    duration: String,
    expected_count: usize,
    field: String,
) {
    let duration = parse_duration_text(&duration).expect("step duration must be a valid duration");
    let session = world
        .active_session
        .as_mut()
        .expect("an active session with subscription must exist");
    let deadline = Instant::now() + duration;
    let mut shared_values = BTreeSet::new();
    let mut observed = Vec::with_capacity(expected_count);

    while observed.len() < expected_count {
        nervix_primitives::task::consume_budget().await;
        let now = Instant::now();
        assert!(
            now < deadline,
            "timed out after receiving {} of {expected_count} subscription payloads; observed \
             {observed:?}",
            observed.len()
        );
        let event = session
            .try_next_subscription(deadline.saturating_duration_since(now))
            .await
            .expect("failed while waiting for subscription payloads")
            .unwrap_or_else(|| {
                panic!(
                    "timed out after receiving {} of {expected_count} subscription payloads; \
                     observed {observed:?}",
                    observed.len()
                )
            });
        let payload = event.payload;
        let value = serde_json::from_str::<serde_json::Value>(&payload)
            .unwrap_or_else(|error| panic!("subscription payload is not valid JSON: {error}"));
        let shared_value = value
            .get(&field)
            .unwrap_or_else(|| panic!("subscription payload {value} has no field '{field}'"))
            .to_string();
        shared_values.insert(shared_value);
        observed.push(payload.clone());
        world.last_subscription_payload = Some(payload);
    }

    assert_eq!(
        shared_values.len(),
        1,
        "expected {expected_count} subscription payloads to share field '{field}', got \
         {shared_values:?} from {observed:?}"
    );
}

