#[then(
    expr = "within {string} {int} generator occurrences preserve rows by {string} on {string} \
            logical cadence with shared timestamp field {string}"
)]
async fn then_generator_occurrences_preserve_branches(
    world: &mut ScenarioWorld,
    duration: String,
    expected_occurrences: usize,
    branch_field: String,
    cadence: String,
    timestamp_field: String,
    #[step] step: &Step,
) {
    let duration = match parse_duration_text(&duration) {
        Ok(duration) => duration,
        Err(error) => panic!("step duration must be valid: {error}"),
    };
    let cadence = match parse_duration_text(&cadence) {
        Ok(cadence) => cadence,
        Err(error) => panic!("logical cadence must be valid: {error}"),
    };
    let expected = expand_placeholders(world, docstring(step));
    let rows = match serde_json::from_str::<Vec<serde_json::Value>>(&expected) {
        Ok(rows) => rows,
        Err(error) => panic!("expected generator source rows must be valid JSON: {error}"),
    };
    let mut observation = common::generator_cadence::GeneratorCadenceObservation::new(
        rows,
        expand_placeholders(world, &branch_field),
        expand_placeholders(world, &timestamp_field),
        cadence,
        expected_occurrences,
    );
    let mut session = world
        .active_session
        .take()
        .assured("an active session with subscription must exist");
    let (session, last_payload) = common::runner_observation::observe_off_the_runner(async move {
        observation.observe(duration, &mut session).await;
        (session, observation.last_payload().cloned())
    })
    .await;
    world.active_session = Some(session);
    world.last_subscription_payload = last_payload;
}

#[then(
    expr = "within {string} generated routes {string} value {int} and {string} value {int} share \
            field {string}"
)]
async fn then_generated_routes_share_field(
    world: &mut ScenarioWorld,
    duration: String,
    first_route: String,
    first_value: i64,
    second_route: String,
    second_value: i64,
    shared_field: String,
) {
    let duration = parse_duration_text(&duration).expect("step duration must be a valid duration");
    let session = world
        .active_session
        .as_mut()
        .expect("an active session with subscription must exist");
    let deadline = Instant::now() + duration;
    let mut routes_by_shared_value = BTreeMap::<String, BTreeSet<String>>::new();
    let mut observed = Vec::new();

    loop {
        nervix_primitives::task::consume_budget().await;
        let now = Instant::now();
        assert!(
            now < deadline,
            "timed out waiting for generated routes '{first_route}' and '{second_route}' to share \
             field '{shared_field}'. observed {observed:?}"
        );
        let event = session
            .try_next_subscription(deadline.saturating_duration_since(now))
            .await
            .expect("failed while waiting for generated route payloads")
            .unwrap_or_else(|| {
                panic!(
                    "timed out waiting for generated routes '{first_route}' and '{second_route}' \
                     to share field '{shared_field}'. observed {observed:?}"
                )
            });
        let payload = event.payload;
        world.last_subscription_payload = Some(payload.clone());
        observed.push(payload.clone());
        let Ok(value) = serde_json::from_str::<serde_json::Value>(&payload) else {
            continue;
        };
        let Some(route) = value.get("route").and_then(serde_json::Value::as_str) else {
            continue;
        };
        let Some(route_value) = value.get("value").and_then(serde_json::Value::as_i64) else {
            continue;
        };
        let expected_value = if route == first_route {
            first_value
        } else if route == second_route {
            second_value
        } else {
            continue;
        };
        if route_value != expected_value {
            continue;
        }
        let Some(shared_value) = value.get(&shared_field) else {
            continue;
        };
        let shared_value = shared_value.to_string();
        let routes = routes_by_shared_value.entry(shared_value).or_default();
        routes.insert(route.to_string());
        if routes.contains(&first_route) && routes.contains(&second_route) {
            return;
        }
    }
}

#[then(expr = "within {string} the relay subscription receives payloads in order")]
async fn then_within_duration_the_stream_subscription_receives_payloads_in_order(
    world: &mut ScenarioWorld,
    duration: String,
    #[step] step: &Step,
) {
    let duration = parse_duration_text(&duration).expect("step duration must be a valid duration");
    let expected_fragments = docstring(step)
        .lines()
        .map(str::trim)
        .filter(|line| !line.is_empty())
        .map(|line| expand_placeholders(world, line))
        .collect::<Vec<_>>();

    assert!(
        !expected_fragments.is_empty(),
        "step docstring must contain at least one expected payload fragment"
    );

    let session = world
        .active_session
        .as_mut()
        .expect("an active session with subscription must exist");
    let deadline = Instant::now() + duration;
    let mut observed = Vec::with_capacity(expected_fragments.len());

    for expected_fragment in &expected_fragments {
        let now = Instant::now();
        assert!(
            now < deadline,
            "timed out waiting for subscription payload fragment {:?}. observed {:?}",
            expected_fragment,
            observed
        );
        let wait = deadline.saturating_duration_since(now);
        let event = session
            .try_next_subscription(wait)
            .await
            .expect("failed while waiting for subscription payloads")
            .unwrap_or_else(|| {
                panic!(
                    "timed out waiting for subscription payload fragment {:?}. observed {:?}",
                    expected_fragment, observed
                )
            });
        let payload = event.payload;
        observed.push(payload.clone());
        world.last_subscription_payload = Some(payload.clone());
        assert!(
            payload.contains(expected_fragment),
            "expected next subscription payload to contain {:?}, got {:?}; observed {:?}",
            expected_fragment,
            payload,
            observed
        );
    }
}

#[then(expr = "within {string} the relay subscription receives payloads containing all fragments")]
async fn then_within_duration_the_stream_subscription_receives_payloads_containing_all_fragments(
    world: &mut ScenarioWorld,
    duration: String,
    #[step] step: &Step,
) {
    receive_subscription_fragment_sets(world, &duration, step, UnmatchedPayloads::Skip, None).await;
}

/// Like the step above, except that every payload arriving before the last fragment set matches
/// must match a set not yet matched, so a record the scenario expects to be dropped fails the step
/// even when it arrives among the expected ones.
#[then(
    expr = "within {string} the relay subscription receives exactly one payload for each fragment \
            set"
)]
async fn then_within_duration_the_stream_subscription_receives_exactly_the_fragment_sets(
    world: &mut ScenarioWorld,
    duration: String,
    #[step] step: &Step,
) {
    receive_subscription_fragment_sets(world, &duration, step, UnmatchedPayloads::Fail, None).await;
}

/// Measures every expected row from publication, so a delayed HTTP response cannot start a new
/// silence window after a valid collection or flush deadline has already passed.
#[then(
    expr = "within {string} the relay subscription receives payloads no sooner than {string} \
            after they were published"
)]
async fn then_subscription_payloads_arrive_after_publication_delay(
    world: &mut ScenarioWorld,
    duration: String,
    delay: String,
    #[step] step: &Step,
) {
    let delay = parse_duration_text(&delay).expect("step delay must be a valid duration");
    let published_at = world
        .last_publish_at
        .expect("a delivery-delay assertion must follow a publishing step");
    receive_subscription_fragment_sets(
        world,
        &duration,
        step,
        UnmatchedPayloads::Fail,
        Some(published_at + delay),
    )
    .await;
}

/// Every payload matching a fragment set carries the same value in the
/// named JSON field, such as the one error reference the members of a failed batch share.
#[then(
    expr = "within {string} the relay subscription receives payloads containing all fragments \
            that share one {string}"
)]
async fn then_within_duration_the_stream_subscription_receives_fragments_sharing_one_field(
    world: &mut ScenarioWorld,
    duration: String,
    field: String,
    #[step] step: &Step,
) {
    let matched =
        receive_subscription_fragment_sets(world, &duration, step, UnmatchedPayloads::Skip, None)
            .await;
    let values = matched
        .iter()
        .map(|payload| {
            let payload: serde_json::Value =
                serde_json::from_str(payload).unwrap_or_else(|error| {
                    panic!("subscription payload {payload:?} is not JSON: {error}")
                });
            payload
                .get(&field)
                .cloned()
                .unwrap_or_else(|| panic!("subscription payload {payload} has no field {field:?}"))
        })
        .collect::<Vec<_>>();
    let Some(first) = values.first() else {
        panic!("no subscription payload matched the expected fragment sets");
    };
    assert!(
        values.iter().all(|value| value == first),
        "payloads matching the fragment sets carry different {field:?} values: {values:?}"
    );
}

/// What a fragment-set wait does with a payload that matches none of the sets still expected.
#[derive(Debug, Clone, Copy)]
enum UnmatchedPayloads {
    /// Other records share the subscription, so the payload is passed over.
    Skip,
    /// The sets name every record the subscription may deliver, so the payload fails the step.
    Fail,
}

/// Every docstring line's `|`-separated fragments, with placeholders expanded.
fn docstring_fragment_sets(world: &ScenarioWorld, step: &Step) -> Vec<Vec<String>> {
    docstring(step)
        .lines()
        .map(str::trim)
        .filter(|line| !line.is_empty())
        .map(|line| {
            line.split('|')
                .map(str::trim)
                .filter(|fragment| !fragment.is_empty())
                .map(|fragment| expand_placeholders(world, fragment))
                .collect::<Vec<_>>()
        })
        .collect::<Vec<_>>()
}

/// Waits until every docstring line's `|`-separated fragments are all found in one subscription
/// payload, and returns the payloads that matched, in the order they arrived.
async fn receive_subscription_fragment_sets(
    world: &mut ScenarioWorld,
    duration: &str,
    step: &Step,
    unmatched: UnmatchedPayloads,
    delivery_not_before: Option<Instant>,
) -> Vec<String> {
    let expected_fragment_sets = docstring_fragment_sets(world, step);
    assert!(
        !expected_fragment_sets.is_empty(),
        "step docstring must contain at least one expected payload fragment set"
    );
    receive_expected_fragment_sets(
        world,
        duration,
        expected_fragment_sets,
        unmatched,
        delivery_not_before,
    )
    .await
}

/// Waits until each of `expected_fragment_sets` is found whole in one subscription payload, and
/// returns the payloads that matched, in the order they arrived. A matching payload that arrives
/// before `delivery_not_before` fails the wait.
async fn receive_expected_fragment_sets(
    world: &mut ScenarioWorld,
    duration: &str,
    expected_fragment_sets: Vec<Vec<String>>,
    unmatched: UnmatchedPayloads,
    delivery_not_before: Option<Instant>,
) -> Vec<String> {
    let duration = parse_duration_text(duration).expect("step duration must be a valid duration");
    let session = world
        .active_session
        .as_mut()
        .expect("an active session with subscription must exist");
    let deadline = Instant::now() + duration;
    let mut remaining = expected_fragment_sets;
    let mut observed = Vec::new();
    let mut matched = Vec::new();

    while !remaining.is_empty() {
        let now = Instant::now();
        assert!(
            now < deadline,
            "timed out waiting for subscription payload fragment sets. expected remaining {:?}, \
             observed {:?}",
            remaining,
            observed
        );
        let wait = deadline.saturating_duration_since(now);
        let event = session
            .try_next_subscription(wait)
            .await
            .expect("failed while waiting for subscription payloads")
            .unwrap_or_else(|| {
                panic!(
                    "timed out waiting for subscription payload fragment sets. expected remaining \
                     {:?}, observed {:?}",
                    remaining, observed
                )
            });
        let payload = event.payload;
        observed.push(payload.clone());
        world.last_subscription_payload = Some(payload.clone());

        let position = remaining
            .iter()
            .position(|fragments| fragments.iter().all(|fragment| payload.contains(fragment)));
        match (position, unmatched) {
            (Some(index), _) => {
                if let Some(not_before) = delivery_not_before {
                    assert!(
                        Instant::now() >= not_before,
                        "subscription payload {payload:?} arrived before its publication-relative \
                         delivery bound"
                    );
                }
                remaining.remove(index);
                matched.push(payload);
            }
            (None, UnmatchedPayloads::Skip) => {}
            (None, UnmatchedPayloads::Fail) => panic!(
                "subscription payload {payload:?} matches no expected fragment set. expected \
                 remaining {remaining:?}, observed {observed:?}"
            ),
        }
    }
    matched
}

